use rocket::http::Status;

use rocket::{ get, post, State };
use rocket::response::stream::TextStream;
use rocket::serde::json::Json;
use async_openai::{
    types::{ ChatCompletionRequestMessageArgs, CreateChatCompletionRequestArgs, Role },
    Client,
};
use futures::StreamExt;
use serde::{ Serialize, Deserialize };
use rocket::routes;
use diesel::r2d2::ConnectionManager;
use diesel::r2d2::Pool;
use diesel::mysql::MysqlConnection;
use uuid::Uuid;
use std::collections::HashMap;

#[get("/template/<template_id>")]
async fn get_template_by_id(
    state: &State<Pool<ConnectionManager<MysqlConnection>>>,
    template_id: String
) -> Json<Option<crate::models::Template>> {
    use crate::schema::templates::dsl::*;
    use diesel::prelude::*;

    let mut connection = state.get().unwrap();
    let result = templates
        .filter(id.eq(template_id))
        .first::<crate::models::Template>(&mut *connection)
        .optional()
        .map_err(|_| Status::InternalServerError)
        .unwrap();

    Json(result)
}

#[derive(Deserialize, Serialize)]
struct TemplateInput {
    content: String,
    model: String,
}

#[post("/template", format = "json", data = "<new_template>")]
async fn create_template(
    state: &State<Pool<ConnectionManager<MysqlConnection>>>,
    new_template: Json<TemplateInput>
) -> Json<HashMap<String, String>> {
    use diesel::prelude::*;
    use crate::schema::templates::dsl::*;

    let new_template_json = new_template.into_inner();
    let mut connection = state.get().unwrap();
    let generated_id = Uuid::new_v4().hyphenated().to_string();

    // Create a new Template instance from the JSON input
    let new_template = crate::models::Template {
        id: generated_id.clone(),
        template: new_template_json.content,
        created_at: chrono::Utc::now().naive_utc(),
        modified_at: chrono::Utc::now().naive_utc(),
        user_id: 1,
        model: new_template_json.model,
    };

    dbg!(&new_template);

    let _new_record = diesel
        ::insert_into(templates)
        .values(new_template)
        .execute(&mut connection)
        .map_err(|_| Status::InternalServerError)
        .unwrap();

    let mut map = HashMap::new();
    map.insert("templateId".to_string(), generated_id);

    Json(map)
}

#[derive(Deserialize)]
struct ChatInput {
    content: String,
    model: Option<String>,
}

#[post("/stream", format = "json", data = "<chat_input>")]
async fn stream(chat_input: Json<ChatInput>) -> TextStream![String] {
    let client = Client::new();
    let model = chat_input.model.clone().unwrap_or_else(|| "gpt-3.5-turbo".to_string());
    let request = CreateChatCompletionRequestArgs::default()
        .model(model)
        .messages([
            ChatCompletionRequestMessageArgs::default()
                .content(chat_input.content.clone())
                .role(Role::User)
                .build()
                .unwrap(),
        ])
        .build()
        .unwrap();

    dbg!(&request);

    let mut stream = client.chat().create_stream(request).await.unwrap();

    TextStream! {
        while let Some(result) = stream.next().await {
            match result {
                Ok(response) => {
                    for chat_choice in &response.choices {
                        if let Some(ref content) = chat_choice.delta.content {
                            yield content.clone();
                        }
                    }
                }
                Err(err) => {
                    yield format!("error: {}", err);
                }
            }
        }
    }
}

#[get("/")]
async fn index() -> String {
    "alive".to_string()
}

pub fn routes() -> Vec<rocket::Route> {
    routes![stream, index, create_template, get_template_by_id]
}

