mod api;
mod cors;
mod db;
mod models;
mod schema;

use rocket::Config;
use rocket::launch;
use api::routes;
use cors::configure_cors;
use db::init_pool;

#[launch]
fn rocket() -> _ {
    dotenv::dotenv().ok();

    for (key, value) in std::env::vars() {
        println!("{}: {}", key, value);
    }

    let database_url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let cors = configure_cors();
    let pool = init_pool(&database_url);

    rocket
        ::build()
        .configure(Config::figment().merge(("databases.mysql_db.url", database_url)))
        .manage(pool)
        .attach(cors)
        .mount("/", routes())
}

