async function executeHandler(req, res) {
  let code = req.body.change;

  // Check if code starts with shebang
  if (!code.startsWith("#!")) {
    code = extractCode(code);
  }

  await executeAndForwardOutput(code, (code, output) => {
    res.json({ output });
  });
}

export { executeHandler };


